var e=({filter:e},{services:n})=>{console.log("[bonus-draws-engine] Hook automat (FILTER) pentru Bonus Draws încărcat cu succes."),e("giveaways.items.update",async(e,n,t)=>{const s=Object.keys(e).find(e=>"sold_tickets"===e.toLowerCase());if(!s)return e;const a=Number(e[s]);if(isNaN(a))return e;const r=t.database;for(const t of n.keys)try{const n=await r("giveaways").where({id:t}).first();if(!n)continue;const s=Number(n.total_tickets)||0;let o=e.bonus_draws||n.bonus_draws,i=[];if("string"==typeof o)try{i=JSON.parse(o)}catch(e){i=[]}else Array.isArray(o)&&(i=o);if(!i||0===i.length||0===s)continue;const c=a/s*100;let u=!1;const l=[...i];for(let e=0;e<l.length;e++){const n=l[e];if(Number(n.percentage)<=c&&!0!==n.is_won){console.log(`[bonus-draws-engine] Giveaway ${t} a atins pragul de ${n.percentage}%. Extragere aleatorie...`);const s=await r("tickets").where({giveaway_id:t}).select("ticket_number","client_name","email","order_id");if(0===s.length){console.warn(`[bonus-draws-engine] Atenție, niciun bilet generat pe giveaway ${t}. Extragere amânată.`);continue}const a=s[Math.floor(Math.random()*s.length)],o=a.client_name||a.email?.split("@")[0]||"Anonim";l[e]={...n,is_won:!0,winner_name:o,winner_ticket:a.ticket_number},u=!0,console.log(`[bonus-draws-engine] 🎉 BONUS DRAW CÂȘTIGAT (${n.percentage}%)! Extras: ${a.ticket_number} -> ${o}`)}}u&&(e.bonus_draws=JSON.stringify(l))}catch(e){console.error("[bonus-draws-engine] Eroare severă procesând un bonus draw",t,e?.message||e)}return e})};export{e as default};
